#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

long long numOfArrays(int n, int m, int k) {
    if (k == 0 || k > n || k > m) return 0;
    long long *prev = calloc((m + 1) * (k + 1), sizeof(long long));
    long long *pref = calloc((m + 1) * (k + 1), sizeof(long long));
    long long *cur = calloc((m + 1) * (k + 1), sizeof(long long));
    long long *curPref = calloc((m + 1) * (k + 1), sizeof(long long));
    #define AT(a, x, y) a[(x) * (k + 1) + (y)]

    for (int value = 1; value <= m; value++) {
        AT(prev, value, 1) = 1;
        AT(pref, value, 1) = (AT(pref, value - 1, 1) + 1) % MOD;
    }
    for (int length = 2; length <= n; length++) {
        for (int maximum = 1; maximum <= m; maximum++) {
            for (int cost = 1; cost <= k; cost++) {
                AT(cur, maximum, cost) = (maximum * AT(prev, maximum, cost) + AT(pref, maximum - 1, cost - 1)) % MOD;
                AT(curPref, maximum, cost) = (AT(curPref, maximum - 1, cost) + AT(cur, maximum, cost)) % MOD;
            }
        }
        long long *tmp = prev; prev = cur; cur = tmp;
        tmp = pref; pref = curPref; curPref = tmp;
        for (int i = 0; i < (m + 1) * (k + 1); i++) { cur[i] = 0; curPref[i] = 0; }
    }
    long long answer = AT(pref, m, k);
    free(prev); free(pref); free(cur); free(curPref);
    return answer;
}

