class Solution {
public:
    int numOfArrays(int n, int m, int k) {
        const long long MOD = 1000000007LL;
        if (k == 0 || k > n || k > m) return 0;
        vector<vector<long long>> prev(m + 1, vector<long long>(k + 1));
        vector<vector<long long>> pref(m + 1, vector<long long>(k + 1));
        for (int value = 1; value <= m; value++) {
            prev[value][1] = 1;
            pref[value][1] = (pref[value - 1][1] + 1) % MOD;
        }
        for (int length = 2; length <= n; length++) {
            vector<vector<long long>> cur(m + 1, vector<long long>(k + 1));
            vector<vector<long long>> curPref(m + 1, vector<long long>(k + 1));
            for (int maximum = 1; maximum <= m; maximum++) {
                for (int cost = 1; cost <= k; cost++) {
                    cur[maximum][cost] = (maximum * prev[maximum][cost] + pref[maximum - 1][cost - 1]) % MOD;
                    curPref[maximum][cost] = (curPref[maximum - 1][cost] + cur[maximum][cost]) % MOD;
                }
            }
            prev.swap(cur);
            pref.swap(curPref);
        }
        return (int)pref[m][k];
    }
};

