class Solution:
    def numOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 1_000_000_007
        if k == 0 or k > n or k > m:
            return 0
        prev = [[0] * (k + 1) for _ in range(m + 1)]
        pref = [[0] * (k + 1) for _ in range(m + 1)]
        for value in range(1, m + 1):
            prev[value][1] = 1
            pref[value][1] = (pref[value - 1][1] + 1) % MOD
        for length in range(2, n + 1):
            cur = [[0] * (k + 1) for _ in range(m + 1)]
            cur_pref = [[0] * (k + 1) for _ in range(m + 1)]
            for maximum in range(1, m + 1):
                for cost in range(1, k + 1):
                    cur[maximum][cost] = (maximum * prev[maximum][cost] + pref[maximum - 1][cost - 1]) % MOD
                    cur_pref[maximum][cost] = (cur_pref[maximum - 1][cost] + cur[maximum][cost]) % MOD
            prev, pref = cur, cur_pref
        return pref[m][k]

